/* ===== Cómo se usa: manual, preguntas frecuentes, derechos y deberes, presentación, simulador y demo =====
   Pedido de Claudio (25-10-2026): todo junto en una pantalla con solapas, para mostrar el proyecto completo. */

var SOLAPAS_AYUDA = [['manual', 'Manual'], ['preguntas', 'Preguntas frecuentes'], ['estatuto', 'Derechos y deberes'], ['presentacion', 'Presentación'], ['simulador', 'Simulador'], ['demo', 'Demo con celulares']];

function vistaAyuda(u, r) {
  var t = (r && r.q.t) || 'manual'; if (!SOLAPAS_AYUDA.some(function (s) { return s[0] === t; })) t = 'manual';
  var cuerpo = t === 'preguntas' ? ayudaPreguntas() : t === 'estatuto' ? ayudaEstatuto(u) : t === 'presentacion' ? ayudaPresentacion() : t === 'simulador' ? ayudaSimulador() : t === 'demo' ? ayudaDemo() : ayudaManual();
  return '<h1>Cómo se usa</h1><p class="gris">Versión ' + VERSION_APP + ' · el manual, las preguntas de quien empieza, las reglas del grupo y todo el material para mostrar el proyecto.</p>' +
    '<nav class="solapas-ayuda" aria-label="Secciones de Cómo se usa">' + SOLAPAS_AYUDA.map(function (s) { return '<a href="#/ayuda?t=' + s[0] + '"' + (s[0] === t ? ' aria-current="page"' : '') + '>' + s[1] + '</a>'; }).join('') + '</nav>' + cuerpo +
    '<div class="aviso seccion">B&amp;D no es una oferta al público ni asesoramiento financiero, legal o impositivo. Las proyecciones son escenarios. Todo lo legal e impositivo lo validan abogado, escribano y contador de Tierra del Fuego.</div>';
}
function acordeon(lista) { return '<section class="apilar seccion">' + lista.map(function (s) { return '<details class="tarjeta"><summary style="cursor:pointer;font-weight:600;min-height:28px">' + s[0] + '</summary><div class="gris ayuda-texto" style="margin-top:10px">' + s[1] + '</div></details>'; }).join('') + '</section>'; }

/* ---------------- manual ---------------- */
function ayudaManual() { return acordeon(SECCIONES_MANUAL.map(function (s) { return [s[0], '<p>' + s[1] + '</p>']; })); }
var SECCIONES_MANUAL = [
  ['Qué es B&D', 'Un fideicomiso de amigos. Cada uno de los 10 socios aporta USD 500 por mes (USD 5.000 el grupo). Cada 10 meses, sin excepción, se compra un departamento de 24 m² o más (el grupo fijó USD 2.000 el m²: 24 m² cuestan USD 48.000 más 5% de gastos, USD 50.400). Se alquila a valor de mercado, siempre con dos modalidades para comparar: alquiler fijo (unos USD 450 por mes por 25 m² en Ushuaia, unos $700.000) o temporario (unas 2,5 veces más, con más gastos y trabajo). La renta y el interés se reinvierten. Desde la segunda compra, los alquileres se suman a los aportes y el crecimiento es compuesto.'],
  ['El logo', 'La casa con B&amp;D y «Building Dreams» (construyendo sueños) abajo. Está en la entrada, en el menú, en el resumen semanal y es el ícono de la app en el celular.'],
  ['Demo con cuatro celulares', 'En Cómo se usa → «Demo con celulares» (o en la dirección de la app terminada en /demo.html) se ven cuatro celulares a la vez, cada uno con su perfil: el socio fundador, una socia de Alfa, una persona invitada a otro fideicomiso que se está dando de alta y alguien que solo mira la vitrina. Cada celular se usa como un teléfono y tiene su botón para volver a empezar. Es para mostrar la app en una reunión.'],
  ['Presentación y simulador', 'En Cómo se usa están la presentación completa para la reunión con los socios (se pasa con las flechas, se ve a pantalla completa y muestra las notas de quien presenta) y el simulador interactivo con todas sus pestañas. Ambos usan los mismos números que la app.'],
  ['Entrar a la app', 'Nadie entra con un botón. La cuenta del socio fundador ya está creada y la app no ofrece crear otra. Para entrar hacen falta correo, clave y el código de Google Authenticator del teléfono, que cambia cada 30 segundos (o la huella o la cara, ver más abajo). La entrada tiene dos opciones bien separadas. <b>«Ya soy socio»</b> es para quien ya tiene cuenta (socios, fundador y quien solo mira): pide correo, clave y el código de Google Authenticator, nunca un código de invitación, y es la que aparece elegida al abrir la app. <b>«Tengo una invitación»</b> es solo la primera vez: el correo del fundador trae un enlace que abre la app con esa opción elegida y el código ya escrito (6 letras, vence a los 7 días); se escribe el correo, se toca «Crear mi cuenta» y se completan los datos. Si alguien se equivoca de opción, la app lo acomoda: un socio que pone su correo en «Tengo una invitación», o una invitación que ya se usó, pasa sola a «Ya soy socio» con el correo escrito; a quien todavía no creó su cuenta y toca «Ya soy socio», la app le indica que use «Tengo una invitación». Después cada socio puede activar Google Authenticator en Mis datos. <b>Seguridad de la cuenta</b> (Mis datos): (1) <b>Códigos de recuperación</b>: al activar Google Authenticator la app da 10 códigos de un solo uso para guardar en papel; si se pierde el teléfono, en el paso del código se toca «¿Perdiste el teléfono? Usá un código de recuperación», se escribe uno y después se configura Google Authenticator en el teléfono nuevo. La app guarda solo una huella de cada código: nadie puede volver a leerlos. (2) <b>Entrar con huella o cara</b>: «Activar en este equipo» y desde ahí, en ese teléfono, la entrada muestra un sensor dorado: se toca, se apoya el dedo o se mira la cámara y entra, sin clave ni código. En otro equipo se entra con correo y clave, y en el paso del código aparece «Usar huella o cara». La huella nunca sale del teléfono: la app guarda solo una llave pública. Se puede quitar de cada equipo. (3) <b>Equipos que entraron</b>: si alguien entra a tu cuenta desde un equipo que nunca usaste, te avisa la campanita en tus otros equipos y, en la versión real, ntfy y un correo. Se anota el tipo de equipo («iPhone · Safari») y la fecha, nunca la ubicación. Si ves uno que no es tuyo, cambiá la clave y avisá al fiduciario. Quien recibe un pase «solo mirar» elige una clave y entra a la vitrina. En la entrada pasan frases de aliento en griego; al pasar el mouse, tocarlas o enfocarlas se frenan y abajo aparece la traducción.'],
  ['Volver y Atrás', 'Arriba a la izquierda de cada pantalla está «← Volver»: te lleva a la pantalla anterior justo donde estabas. Cada ventana que se abre encima tiene «← Atrás»: vuelve a la ventana anterior (por ejemplo, del simulador de carteras a las inversiones de hoy) o la cierra si era la primera. La ✕ cierra todas.'],
  ['El menú', 'La barra de arriba (☰, «← Volver», el fideicomiso y la campanita) acompaña el desplazamiento: aunque bajes hasta el final de una pantalla larga, sigue a la vista y el ☰ abre el menú sin tener que subir. En la computadora podés dejar el menú fijo a la vista con «📌 Fijo», o tocar «📌 Fijar» para que se oculte solo y se abra con ☰. Si la pantalla es baja, el menú se desplaza: siempre se ven todas las opciones.'],
  ['Pagar el aporte', 'Menú Pagar. Se paga del 1 al 10 de cada mes, en pesos (a la cotización vendedora más alta del día entre los bancos (incluido el Banco Nación)), dólares o euros, con Mercado Pago, tarjeta de crédito (en 1, 3, 6 o 12 cuotas: las financia tu banco y el fideicomiso cobra completo), transferencia o transferencia desde el exterior. La app no guarda el número de la tarjeta: solo la marca y los últimos 4 números en el recibo. Cada pago compra UP al valor del día y genera su recibo. Arriba se ve el estado de un vistazo: un anillo con cuánto llevás del ciclo, «Estás al día», «Te falta» o «Debés» en grande con su color, qué meses ya pagaste y los meses del ciclo como casilleros que se llenan. Para elegir cuánto ponés hay una perilla con imanes en «Lo pactado», «Completar el ciclo» y «Con el extra máximo»: mientras la movés, la cifra grande, lo que cambia (si quedás al día, cuántas cuotas cubrís, cuánto es extra y cuántas UP compra) y el total a pagar se actualizan solos, y arriba se ve rayado lo que cubriría ese pago. «¿Puedo pagar menos algún mes?» explica el mínimo de la mitad por mes. En «Mis pagos», «Lo que compra tu aporte» y lo que cambia con el monto, las cifras aparecen en la moneda que elegiste (pesos o euros) con los dólares al lado: lo pagado en esa moneda va exacto y lo pagado en otra, con «≈» al dólar del día en que se pagó. Para tus UP cuenta siempre lo que entró en dólares.'],
  ['Si me atraso', 'Desde el día 11 a las 0 h la mora es automática: corre un interés de 12% anual en dólares, segundo a segundo (unos USD 0,16 por día por cada aporte), y se ve en rojo, titilando. Mientras no pagues, lo que debés se descuenta de tu parte en las ganancias (art. 25) y, cuando pagás, tus USD 500 compran UP al valor de ese día, que ya subió: recibís menos UP. A los 30 días se suspenden tu voto y tu parte de los alquileres e intereses (art. 26). Con más de 90 días la Carta prevé la exclusión con aviso y defensa. Opciones: pagar todo junto, tarjeta en cuotas, pagar vencido y mes juntos, compensación con tu parte de las ganancias o un plan especial aprobado por la Asamblea (6 de 10).'],
  ['Unidades de participación (UP)', 'UP quiere decir «unidad de participación»: es tu porción del fideicomiso, como la cuotaparte de un fondo. El patrimonio (caja + inversiones + inmuebles) dividido por las UP da el valor de cada UP. Empezó en USD 100 y cambia todos los días con las ganancias y los gastos. El aporte fijo es de USD 500 por mes; lo que cambia es cuántas UP compra. Así, quien paga tarde o entra después compra al valor indexado por las ganancias del grupo y no se lleva lo que ganaron los demás. Tu parte es tus UP por ese valor. No es 10% justo si alguien no pagó el mes o pagó tarde: tocá «Mi parte hoy» en Inicio para verlo explicado.'],
  ['Inicio', 'Arriba: el fideicomiso (10 socios · USD 500 por mes · 10 meses · building dreams). Tocando el reloj del ciclo se abren las inversiones de hoy, en vivo. Debajo, dos tarjetas parejas: los departamentos (la torre crece con cada compra; tocá un piso para ver el valor del m² hoy, y tocá un departamento de la lista para ver su ficha y, si querés, pedir quedarte con él) y la rueda de aportes del ciclo (cada porción un socio, cada anillo un mes; «Ver como tabla» abre la tabla). Al final, la proyección a 10 años.'],
  ['Mi meta de ingresos', 'Menú «Mi meta de ingresos». Con las barras elegís cuánto querés cobrar por mes de renta dentro de unos años (en dólares de hoy), en cuántos años y cuánto aportás. La app calcula, con el mismo motor del simulador, cuánto cobrarías con el plan del grupo, cuánto tendrías que aportar por mes para llegar, en qué año llegás con el aporte actual y compara caminos: alquiler fijo, temporario o mitad y mitad, comprar por debajo del valor y refaccionar antes de alquilar (con el costo y los meses de la refacción), subir el aporte un poco cada año y vender un departamento cada tanto para recomprar. Cada camino muestra su renta, su patrimonio y su riesgo. Es una guía para decidir, no una promesa: los números dependen del escenario.'],
  ['Inversiones de hoy, en vivo', 'Muestra dónde está invertida la espera (cuenta remunerada, fondo de dinero en dólares, letras del Tesoro de EE. UU., obligaciones negociables), cuánto rinde cada parte por año y por día, cuánto vale en este segundo, cuánto habría si la sacáramos hoy (descontado lo que cuesta vender cada instrumento) y cuándo se invirtió. Se ve el total o tu parte, con los descuentos si estás atrasado. «Simular otra cartera» compara carteras modelo o una armada por vos (con los topes del contrato) y la podés proponer a votación.'],
  ['Proyección a 10 años', 'Está en Inicio y es la única de la app. Dos gráficos lado a lado, con la misma escala: <b>A · Cada 10 meses</b> (la regla del contrato: se compra con toda la caja y cada departamento sale un poco más grande) y <b>B · Siempre 24 m²</b> (se compra uno apenas alcanza la plata de aportes + alquileres + inversión, así las compras se hacen cada vez más seguido; cambiar a B necesita unanimidad). Cada uno muestra lo que ganaría tu parte con alquiler fijo (dorado) y temporario (rosa) contra la meta del 6% (gris punteada); el número al final de cada línea es la ganancia al año 10 y las rayitas de abajo son las compras. Debajo, los departamentos al año 10 como cuadraditos (más grande el cuadradito, más m²) y una tabla con cuántos, de qué tamaño, la renta, lo que vale tu parte y la TIR. Al mover el dedo sobre cualquiera se mueven los dos y abajo se lee el mes («Mes 20 = 1 año y 8 meses desde que empezó»), lo que pusiste y lo que vale tu parte en las cuatro opciones, con de dónde sale: lo que pusiste + intereses de la caja mientras espera cada compra + alquileres + suba del m² − escritura y sellos. Todo es sin vender nada, como la UP. Debajo, <b>¿Cuándo rueda sola?</b>: el mes en que lo que el fideicomiso produce solo en 10 meses (alquileres + intereses de la caja, con todo capitalizado: la caja de aportes y alquileres rinde cada mes, cada departamento sube con el m² y su alquiler con él) alcanza para comprar un 24 m² al precio indexado de ese momento, con la escritura; se comprueba simulando que se deja de aportar desde ese mes y se cuenta cuántos departamentos se siguen comprando. En los gráficos es el círculo hueco. Al final, la sugerencia con pros y contras. Las solapas cambian el escenario (pesimista, básico, optimista). «¿Por qué comprar y no dejarlo en plazo fijo?» muestra las palancas para ganar más.'],
  ['La TIR', 'Es el interés anual compuesto en dólares que ganó tu plata, contando el día exacto de cada aporte: si es 6%, es como si cada dólar hubiera estado a 6% anual desde el día que lo pusiste. Cuenta todo lo que pasó de verdad, cada cosa en su fecha: el interés de cada aporte mientras espera y cada alquiler cobrado. El primer año da menos porque la plata espera la compra en instrumentos de bajo riesgo (hoy alrededor de 3,9%), una reserva casi no rinde y el primer alquiler llega después de la compra. La escritura no baja la TIR (el departamento se cuenta por todo lo que costó), pero la suba del m² recién aparece al tasar o vender; con los alquileres sube en los años siguientes. Ninguna inversión de bajo riesgo asegura 6% desde el primer mes; un plazo fijo en dólares paga alrededor de 1,5%. Tocá «Mi rendimiento real» para ver la TIR proyectada por escenario, con alquiler fijo y temporario.'],
  ['Mis inversiones', 'Dos maneras de medir: «Cómo le va al fideicomiso» es lo que subió la UP desde USD 100 (igual para todos, mide la gestión) con su gráfico mes a mes; «Cómo le va a mi plata» es tu TIR, que depende de cuándo pagaste cada aporte. Además: cuánto aportaste, cuánto vale tu parte, tu ganancia contra la meta del 6% y un plazo fijo en dólares, «Cómo te fue» por ciclo (tarjetas) o mes a mes (casilleros), con cuántos dólares vas adelante o atrás de lo que valdrían tus mismos aportes al 6% por año y en qué está invertido el fideicomiso. La proyección a 10 años no se repite acá: el botón «Ver la proyección» lleva a la de Inicio. «Tu parte vale hoy» y «Rinde por año» abren «Tu ganancia, explicada». Si compraste un departamento del fideicomiso, tu parte que se cubrió con ese departamento cuenta como cobrada en tu TIR.'],
  ['Cómo te fue: por ciclo y mes a mes', 'En Mis inversiones. <b>Por ciclo</b>: una tarjeta por ciclo, como un piso de la torre, con tu capital, la carrera «vos contra la meta del 6%» desde tu primer aporte (adelante o atrás, en dólares), lo que ganaste solo en ese ciclo, la TIR en un medidor con la marca del 6% y «¿De dónde salió?»: rendimiento de la espera, alquileres, gastos e impuestos de todo el fideicomiso y tu parte. Deslizá para ver los otros ciclos. <b>Mes a mes</b>: un casillero por mes, en filas de un ciclo (el más nuevo arriba), que se llena con cuánto llevabas de la ganancia de la meta (verde si la pasaste; 🏠 el mes de compra); al tocarlo aparece el detalle de ese mes. La tabla con todos los números sigue en «Ver todos los números en una tabla».'],
  ['¿Solo, con menos o con más socios?', 'En Inicio, en Tu ganancia y en la pregunta «¿Por qué en un grupo de 10 y no solo?». La carrera de 10 años de los mismos USD 500 por mes de cada persona por cinco caminos: plazo fijo en dólares, letras del Tesoro, solo comprando un 24 m² cuando junta, y en grupo de 5, 10 o 20 socios (comprando cada 20, 10 o 5 meses con toda la caja). Con «▶ Correr los 10 años» las barras avanzan solas. Abajo: por qué 10 (primera compra, departamentos, lo de cada socio, TIR y votos para comprar) y la comparación en 7 mercados (Ushuaia, Buenos Aires, Córdoba, España y Portugal del interior, Grecia y Hungría), cada uno con de dónde salen sus números y si están verificados. Con los números de hoy el grupo gana claro en Ushuaia, Buenos Aires y Córdoba; en Europa la ventaja casi desaparece.'],
  ['Probar otros números: la torre en el tiempo', 'En «Proyección a 10 años y probar otros números», debajo del gráfico compuesto, la torre se arma con el tiempo: con el deslizador o con «▶ Ver cómo crece» la grúa sube un tramo por mes, en el mes de compra se completa el piso y los que faltan quedan punteados. Va junto con el cursor del gráfico (mover uno mueve el otro) y muestra, mes a mes, los departamentos, el alquiler neto, el valor del grupo y lo aportado. Ya no tiene tope de pisos.'],
  ['Inversión de espera', 'El día 11 de cada mes lo cobrado se invierte con la política vigente: ningún aporte queda quieto. En el mes 10 se rescata todo para comprar. Antes del primer aporte del ciclo siguiente la campanita pide decidir la cartera del ciclo; si no se vota, sigue la vigente. En Mercado está el radar del día y por qué no todo va a lo que más rinde (la reserva tiene que estar disponible y el contrato pone tope de 30% por instrumento). La tasa de las letras del Tesoro de EE. UU. sale de la última subasta de letras a 26 semanas (fiscaldata), que es lo que se cobra al comprar hoy.'],
  ['Oportunidades', 'Búsqueda automática todos los días a las 6:00 y a las 11:00 (cuando ya abrieron los mercados) y aviso a las 12:00 con la «🚨 oportunidad única» y la votación exprés lista: lo hace el servidor con fuentes permitidas (las alertas por correo de cada portal del país y del exterior, la API de MercadoLibre y de Idealista, y las páginas públicas de remates y subastas). Departamentos, en pozo, terrenos o loteos y cocheras. Cada aviso se mide primero por el precio del m² contra el valor de la zona («✓ conviene mirarla» o «✗ no conviene por precio»): un precio total bajo puede ser caro por m². Después, «¿Qué conviene hacer con esta oferta?» compara lo que gana por año cada salida, con todos los costos: alquilar fijo, temporario, arreglar y alquilar, arreglar y revender, o revender tal cual. Al revender no se supone el promedio de la zona: solo una parte de la diferencia (60% arreglado, 35% tal cual; se cambia en «Cambiar los supuestos»). También busca departamentos chicos (desde 18 m²) para revender o alquilar: los de menos de 24 m² se marcan «fuera de reglas» porque los vota la Asamblea por mayoría calificada. Cada oferta trae la sugerencia de la app con pros y contras, la calculadora «¿Y si el vendedor financia el saldo?», el contacto, la reserva y dos formas de votar: la votación exprés de 24 horas (con las opciones que calcula la app; si ninguna llega a la mayoría, no se compra) o la común. Hoy la app trae avisos reales relevados el 25-10-2026 (Argenprop, Mudafy, Zonaprop, MercadoLibre y el Banco Ciudad) con su link; un remate que ya se hizo queda como referencia de precio. «Cargar una que vi» suma lo que alguien encontró (las redes sociales no se recorren solas porque sus reglas lo prohíben); para terrenos y cocheras se carga además el valor de referencia de la zona. Fuentes europeas: las alertas por correo de Idealista, Fotocasa, Pisos.com y Habitaclia (España), Immobiliare.it y Casa.it (Italia), Idealista e Imovirtual (Portugal), Spitogatos y XE (Grecia), Imot (Bulgaria), Njuškalo (Croacia) y Nepremičnine (Eslovenia), más la API oficial de Idealista. Los valores de referencia de España, Italia y Portugal se revisaron el 26-10-2026 con Idealista, Immobiliare.it y Doutor Finanças; los euros se pasan a dólares a 1,12 (Banco Central Europeo). Con «Ideas para diversificar» se abre la ficha de la Estación Fin del Mundo 24x7 (lockers, secado de ropa técnica y carga eléctrica sin personal), con perillas para cada supuesto, cuánto se invierte, cuánto deja por año, en cuánto se recupera y su TIR contra la de un departamento; separa lo verificado de lo supuesto. Es una idea a validar con un piloto, no una inversión aprobada: diversificar cambia el contrato y va por unanimidad.'],
  ['Votaciones', 'Un socio, un voto. Ordinarias 6 de 10; comprar o cambiar la inversión de espera 7 de 10; vender, gravar o endeudarse 8 de 10; cambiar aporte, ciclo o contrato, unanimidad. Quien tiene interés propio en el tema no vota y la mayoría se cuenta sin él (por ejemplo, 8 de 9). Algunas decisiones tienen varias opciones: gana la que llega a la mayoría y, si ninguna llega, rige la regla del contrato. Una propuesta de inversión muestra su rendimiento con las tasas del día, cuánto daría por mes contra la vigente y qué quiere decir cada parte. Cada propuesta de inversión abierta trae arriba una «Revisión automática» (idea del X-ray de Ghostfolio): dice en palabras simples si reparte el 100%, si tiene algo prohibido (criptomonedas o acciones), si algún instrumento pasa el 30%, si rinde más o menos que lo de hoy y cuántos dólares por mes, si traba plata hasta después de la compra, si deja la reserva disponible y si tiene más riesgo; al final, un veredicto: se puede votar tranquilo, hay puntos para mirar o no cumple el contrato. La misma revisión aparece en «Simular otra cartera» y en la propuesta automática de Mercado. Con «¿Qué podemos votar?» se ven los 21 temas que se pueden plantear, agrupados por la mayoría que necesitan (con las bancas que hacen falta), lo que cada socio puede hacer sin votar y los temas que la Carta no define con claridad (tasa de mora, cambio de fiduciario, reparto de alquileres, diversificar), marcados «a definir con el abogado». «Proponerlo» abre la nueva votación ya completa.'],
  ['Quedarse con un departamento', 'Un socio al día puede pedir quedarse con un departamento del fideicomiso: en Votaciones → «Quedarme con un departamento», o tocando el departamento en Inicio. Carga la tasación de un tasador matriculado e independiente; el precio es el mayor entre la tasación y lo que le costó al fideicomiso (así nadie pierde los gastos de compra). La app muestra las cuentas: cuánto paga a los demás, cuántas UP se le dan de baja por su propia parte y cuántas le quedan (sigue siendo socio). Vota la Asamblea con mayoría calificada, sin el voto del comprador. Si se aprueba y se firma la escritura, el fiduciario registra la venta: entra la plata a la caja, el valor de la UP de los demás no cambia, queda el acta para firmar y se abre la votación de qué hacer con la plata (sumarla a la próxima compra, comprar un departamento de reemplazo o invertirla en la espera; sin mayoría, se suma a la próxima compra). El fiduciario no puede comprar: lo prohíbe la ley (art. 1676 del Código Civil y Comercial).'],
  ['Compra con saldo en cuotas', 'Si el vendedor necesita plata rápido, el fideicomiso puede pagarle ya lo que tiene en caja y el resto en cuotas fijas en dólares, sin interés ni indexación, que vencen del 1 al 10 como los aportes. En cada oportunidad, «¿Y si el vendedor financia el saldo?» calcula el saldo, la cuota, los vencimientos, cuánto pesa en lo que entra por mes, cuánto se paga antes de la próxima compra y cuánto se gana por comprar ya; trae una propuesta lista para mandarle al vendedor. Tope del estatuto: saldo de hasta 30% del costo y hasta 12 cuotas; lo vota la Asamblea por mayoría calificada. Cuando se firma la escritura, el fiduciario toca «Registrar la compra» en la votación aprobada: el departamento entra completo, la deuda queda como pasivo y se arma el plan de cuotas. En Inicio y en la Carpeta contable se ven los Saldos deudores; la campanita avisa 7 días antes de cada vencimiento y el fiduciario registra cada pago con un toque. El valor de la UP descuenta lo que se debe.'],
  ['Préstamo para comprar más', 'En Oportunidades → «Préstamo para comprar más» se calcula si conviene pedir un préstamo para comprar un departamento extra ya. Se elige el valor del departamento, qué parte se paga con el préstamo (los bancos suelen prestar 50% a 70%; el resto lo pone la caja), la tasa fija y el plazo. La app compara el grupo a 10 años con y sin préstamo y revisa cinco condiciones del estatuto: que el departamento rinda (renta neta + suba del m²) al menos 2 puntos más que la tasa, que la renta cubra 1,3 veces la cuota, que la deuda no pase del 40% del patrimonio, que nadie dé garantía personal y que pase la prueba de estrés (alquiler −20%, sin suba, tasa +3 puntos). Si todo da, se puede proponer a votación (mayoría calificada).'],
  ['Estadísticas', 'Menú «Estadísticas»: la UP, el patrimonio, los inmuebles, las deudas, los ingresos, los egresos y la TIR del grupo; filtros por categoría (aportes, alquileres, inversiones, compras, ventas, préstamos y deudas, gastos), socio, departamento y fechas; agrupado por mes, categoría, departamento o socio. Tocando una fila se filtra por ella y se pasa a la agrupación siguiente (por ejemplo: un mes → sus categorías). Abajo: la rentabilidad de cada departamento, los saldos a fin de cada mes, cada movimiento con su recibo y la bitácora de quién hizo cada acción. «Bajar en planilla» arma el archivo para el contador. Para elegir qué mirar hay tarjetas grandes con ícono: Período (Este mes, Últimos 3 meses, Este ciclo, Último año, Desde el inicio u Otras fechas), Qué (cada tipo con cuántos movimientos tiene), Quién, Dónde y Ver (mes por mes, por tipo, por departamento o por socio); al tocarlas se abre el selector de siempre del teléfono. Abajo, cada mes (o lo que elijas) es una tarjeta que dice cuánto entró, cuánto salió y cuánto quedó a favor, con barras verde y roja; si ese mes se pasó plata a la inversión de espera, lo aclara aparte (no es un gasto: sigue siendo del grupo). Más abajo, «Lo que va a entrar y salir en los próximos 12 meses» (idea de Actual Budget): parte de la plata que hay hoy y suma mes a mes los aportes pactados, los alquileres de hoy, lo que rinde la inversión de espera a la tasa de hoy, los gastos del último mes e ingresos brutos; en el mes de la compra muestra el departamento que se compraría con toda la caja menos la reserva, y desde el mes siguiente cuenta su alquiler. Columnas con lo que queda en la caja cada mes (la dorada es la compra) y una tarjeta por mes. Es una estimación: si alguien se atrasa o cambia una tasa, cambia.'],
  ['Sugerencias, pros, contras y preguntas', 'Cada cálculo termina con «💡 Lo que te sugiere la app»: qué sería lo mejor para el grupo, sus pros y sus contras. Debajo, «Preguntale a la app»: botones con las preguntas más comunes y un lugar para escribir la tuya. Las respuestas salen de las preguntas preparadas con los números de esa cuenta; si no hay una que encaje, contesta la IA gratuita que trae Chrome en el propio equipo (la pregunta no sale de tu computadora) o, en la fase 2, el asistente gratuito del servidor (Gemini, plan sin costo, que recibe solo los números y la pregunta). Si nada de eso está, la pregunta se lleva al chat del grupo con un toque. No escribas datos personales en las preguntas.'],
  ['Colores, tablas y listas', 'Cada sección tiene su color (Inicio dorado, Inversiones cian, Mi meta verde, Estadísticas violeta, Oportunidades coral, Votaciones rosa…) en el título, las tarjetas, las tablas y el ícono del menú. Las tablas entran animadas, se iluminan al pasar y se ordenan tocando el título de una columna (▲ ▼); tocando una fila se marca. En el celular cada fila se lee como una tarjeta, con el nombre de cada dato al lado de su valor. Los números con signo se pintan solos: verde lo que suma, rojo lo que resta. Las hojas para imprimir quedan sobrias. Las tablas con números tienen aspecto de cartera de inversiones: debajo de cada número, una barrita fina que muestra cuánto es comparado con los demás de la columna (crece cuando la tabla aparece), los números cuentan desde cero, y lo que sube lleva ▲ verde y lo que baja ▼ rojo.'],
  ['Debate antes de votar', 'Cada votación tiene su debate (🗣️): argumentos a favor y en contra, cortos y con números si los hay. Con «👍 Apoyar» cada socio suma su apoyo a los que comparte, y arriba se ve lo más apoyado de cada lado. Al votar, se puede dejar el motivo («Por qué votás así»): lo ven los socios en «Votos con motivo». Quien tiene interés propio puede argumentar, pero no vota. Idea de Loomio y DemocracyOS. Los argumentos y motivos los ven solo los socios de ese fideicomiso; en la bitácora queda que alguien opinó, no lo que escribió.'],
  ['Inquilinos: contrato, recibos y atrasos', 'Tocando un departamento en Inicio se ve si el alquiler está al día, pendiente o atrasado. El fiduciario abre la «Ficha del inquilino»: los datos mínimos (nombre, contacto y DNI solo si se firma contrato), el contrato de locación modelo (con la libertad de pacto en moneda, plazo y ajuste vigente; a revisar por un abogado), y los cobros mes a mes. «Registrar el cobro» lo anota en la carpeta contable como alquiler y arma el recibo, que se imprime o se manda por correo o WhatsApp. Si un mes pasa el día de pago, la campanita avisa «Alquiler atrasado» (sin el nombre del inquilino) y «Mandar recordatorio» abre el mensaje listo. «Terminar el contrato» borra el teléfono y el correo del inquilino. Los socios ven solo si está al día.'],
  ['Avisos por varios canales', 'En Mis datos → «Avisos por varios canales» cada socio elige por dónde le llegan los avisos de la campanita, a la vez: correo, ntfy, Telegram (abriendo el bot del fideicomiso y poniendo su número de chat) y WhatsApp (con la clave gratuita de CallMeBot). Los manda el servidor (servidor/avisos-canales.gs), gratis, y nunca llevan nombres ni montos: solo invitan a abrir la app. En modo prueba se guardan los canales pero no se manda nada. Idea de Apprise.'],
  ['Avisos', 'La campanita muestra los avisos nuevos con un número y suena un «din-don» cuando llega uno (se puede apagar en Mis datos). Al abrirlos se borran; los pagos que siguen pendientes vuelven a avisar al día siguiente. Para que el teléfono suene con la app cerrada: en Mis datos → «Avisos con la app cerrada» se crea un canal secreto y se escucha con la app gratuita ntfy; el botón «Mandarme un aviso de prueba» lo comprueba. Los avisos por ntfy no llevan nombres ni montos. El envío diario lo hace el servidor (servidor/avisos-ntfy.gs).'],
  ['Chat de socios', 'Cada fideicomiso tiene su chat: el del grupo y uno privado con cada socio. Solo entran sus socios. La app trae los últimos 30 mensajes de cada conversación (y los anteriores si los pedís). Con «📊 Encuesta» se pregunta algo con 2 a 5 opciones y cada uno vota con un toque; es informal. Quien la creó o el socio fundador la puede pasar a votación formal. No mandes datos bancarios ni claves.'],
  ['Mi carpeta impositiva', 'Según tu situación (monotributo, responsable inscripto, Ganancias inscripto o no) la app arma tus obligaciones del año, tus aportes mes a mes con el dólar del Banco Nación y su equivalente en pesos, tu participación al 31 de diciembre (para Bienes personales) y tu parte del resultado (para Ganancias). Se imprime en PDF, se baja en planilla y se manda a tu contador. No reemplaza al contador.'],
  ['Resumen semanal', 'Cada domingo a las 20 h te llega por correo un PDF con tu parte, cómo cambió en la semana, tus aportes, dónde está la plata, los departamentos y lo que hay que votar. En la app se ve y se guarda en PDF; el envío automático por correo lo hace el servidor (fase 2). Se desactiva en Mis datos.'],
  ['Contratos y firmas', 'Regla de B&D, que la app aplica sola: firma electrónica para votos, actas, la Carta y las adendas; firma digital (firmar.gob.ar) o escribano para el contrato y la adhesión a un fideicomiso. La firma electrónica deja la huella SHA-256 del texto y la cadena de firmas con fecha, hora y CUIT. Un documento puede tener orden de firma: firma de a uno, solo el que le toca. «Auditoría (PDF)» arma la constancia con todo lo que pasó. El contrato de adhesión de cada socio se arma solo con sus datos: el texto es el mismo para todos y solo se editan los datos de filiación, fiscales y de cobro (Contratos → «Mi contrato de adhesión»; el fundador elige el socio y lo manda a firmar con firma digital o escribano). El nombre, el DNI y el CUIT los cambia el fiduciario, con constancia.'],
  ['Derechos y deberes', 'En Cómo se usa → «Derechos y deberes» está el estatuto completo (Anexo I del contrato): definiciones, derechos y deberes de cada socio, mora y sanciones, Asamblea y mayorías, venta de un inmueble a un socio, el fiduciario, firmas y datos, inmuebles en el exterior, conflictos y cláusulas generales. Se lee en la app, se baja en texto y se imprime. Es un modelo para que lo revise un abogado matriculado en Tierra del Fuego.'],
  ['Validar una firma digital', 'En Contratos → «Subir un PDF firmado digitalmente» la app valida la firma en tu propio teléfono, sin mandar el PDF a ningún lado: que el PDF no cambió desde que se firmó, que la firma corresponde al certificado, quién firmó y su CUIL, si el certificado estaba vigente y si el emisor es un certificador licenciado de la Argentina. Lo único que no puede consultar es si el certificado fue revocado: eso lo muestran el validador de firmar.gob.ar o Adobe Acrobat Reader.'],
  ['Fideicomisos griegos', 'Cada socio ve sus fideicomisos y las propuestas abiertas. Un fideicomiso cerrado lo ven solo sus socios y el socio fundador. Un fideicomiso solicitado tiene 90 días para completarse: una semana antes la app avisa a sus integrantes y al día 90 lo disuelve sola, como aceptaron en el pre-acuerdo. Cuando se completa, la app agenda una reunión virtual dentro de los primeros 5 días hábiles.'],
  ['Vitrina para invitados', 'Una persona invitada «solo a mirar» ve la vitrina: los fideicomisos que ya funcionan, con sus números, dónde invierten, qué compraron y su algoritmo, sin nombres ni datos personales y sin poder cambiar nada.'],
  ['Carpeta contable y conciliación', 'Se arma sola cada día, semana y mes: libro diario por partida doble, mayor, balances, registro de UP, aportes y mora, impuestos estimados de la AREF y datos fiscales. La venta de un departamento a un socio se registra en tres líneas: el inmueble llevado al precio de venta, lo que entró a la caja y la parte del comprador cancelada con sus UP (cuentas 3.1.02 y 4.1.04). Una vez por mes el fiduciario concilia el extracto del banco. Reglas para clasificar solo el extracto (idea de Firefly III): al decidir un renglón podés tildar «Recordar» con las palabras del concepto (por ejemplo «INMOBILIARIA AUSTRAL» → alquiler del Departamento 1) y la próxima conciliación lo clasifica sola; también se crean, se ven y se borran en «Reglas para clasificar el extracto solo». Las ve solo el fiduciario, porque pueden tener nombres de inquilinos o proveedores.'],
  ['Privacidad', 'Tus datos personales y fiscales los ven vos y el fiduciario; el contador recibe lo fiscal. Los demás socios ven tu nombre, aportes y participación. Cuando el fiduciario abre la ficha o el contrato de adhesión de un socio, queda anotado en la bitácora. Los datos de los inquilinos los ve solo el fiduciario; al terminar el contrato se borran su teléfono y su correo, y el nombre y el DNI quedan 10 años en los recibos y el contrato, como exige la ley contable. El teléfono de WhatsApp, el chat de Telegram y la clave de CallMeBot de cada socio los ve solo él (y el servidor para mandar los avisos). Los invitados que solo miran no ven ningún dato personal. La clave se guarda como huella y la clave de Google Authenticator nunca se muestra después de activarla. La tarjeta no se guarda. De las publicaciones del radar se guarda solo lo que el vendedor publicó. Lo que cargás en «Mi meta de ingresos» no se guarda: se calcula en tu teléfono. Las preguntas a la app no llevan datos personales: la IA de Chrome las procesa en tu equipo y el asistente del servidor (fase 2) recibe solo los números de la cuenta y la pregunta. En este modo prueba todo queda en este equipo; en la versión real viaja cifrado a una base con reglas por usuario.'],
  ['Lo que falta para usarla de verdad', '1) Servidor y base de datos (Firebase) para que todos vean lo mismo, con la clave de Google Authenticator guardada del lado del servidor. 2) Correos automáticos y resumen semanal (servidor/resumen-semanal.gs). 3) Cuenta de Mercado Pago del fideicomiso y el programa de cobros (servidor/pagos.gs). 4) Avisos diarios con la app cerrada por ntfy (servidor/avisos-ntfy.gs), el radar de oportunidades en vivo a las 6, 11 y 12 (servidor/radar-oportunidades.gs: un Gmail del fideicomiso suscripto a las alertas de los portales y las claves gratuitas de MercadoLibre e Idealista) el asistente gratuito (servidor/asistente.gs, clave gratis de Google AI Studio) y los avisos por varios canales (servidor/avisos-canales.gs: bot de Telegram y CallMeBot para WhatsApp, gratis). 5) Constituir el fideicomiso: el paso a paso está en Preguntas frecuentes. 6) Revisión de abogado, escribano y contador.']
];

/* ---------------- preguntas frecuentes ---------------- */
function paramsBase(mk, o) { return Object.assign(applyMarket(Object.assign({}, DEFAULTS), mk || 'ushuaia'), { reserve: 0 }, o || {}); }
function ayudaPreguntas() {
  var gm = simulate(paramsBase()), g8 = simulate(paramsBase(null, { setup: 8 })), gt = simulate(paramsBase(null, { mix: 1 })), sm = simulate(paramsBase(null, { members: 1, strategy: 'umbral' })), st = simulate(paramsBase(null, { members: 1, strategy: 'umbral', mix: 1 }));
  var mesSolo = sm.purchases.length ? sm.purchases[0].month : null, N = 10;
  var bm = simulate(paramsBase('buenosaires')), bt = simulate(paramsBase('buenosaires', { mix: 1 }));
  var M = MARKETS.buenosaires, brutoT = M.rent24 * M.mult;
  var anios = function (m) { return Math.floor(m / 12) + ' años' + (m % 12 ? ' y ' + (m % 12) + ' meses' : ''); };
  var Q = [
    ['¿El precio del m² y los alquileres son reales?', '<p>Hay dos números. La <b>regla del grupo</b> (USD 2.000 el m² en Ushuaia y USD 450 de alquiler por 25 m²) es fija: la pusieron los socios y solo se cambia votando. El alquiler se revisó el 26-10-2026 con los avisos de Ushuaia y Buenos Aires: un monoambiente de unos 25 m² se pide entre $450.000 y $950.000 por mes según la zona (en Ushuaia, entre $700.000 y $750.000 más expensas), así que se pasó de USD 300 a USD 450 (unos $700.000 al dólar oficial). El temporario en Ushuaia se calcula 2,5 veces el fijo (USD 1.125 por mes, bruto). Al lado, la app muestra el <b>mercado del día</b>: todos los días a las 7 el servidor lee los avisos publicados en MercadoLibre (Ushuaia y Buenos Aires); si MercadoLibre falla o trae pocos avisos, usa solo las alertas por correo de Zonaprop y, si tampoco alcanzan, las de Argenprop. Si ninguna trae datos, queda el último con su fecha y al fiduciario le llega un correo a los 3 días y calcula el precio del medio (la mediana) del m² en venta y del alquiler. Lo ves en <b>Mercado</b> y en <b>Valor del m² hoy</b>, con cuántos avisos se usaron y la fecha. Son precios pedidos, no de cierre: sirven para saber si la regla está cerca del mercado y para negociar. Las cotizaciones del dólar y las tasas sí son del día, de fuentes oficiales y de los bancos.</p>'],
    ['¿Puedo poner más o menos que USD 500 algún mes?', '<p>Sí: es la <b>cuota flexible</b>. En <b>Pagar</b> aparece siempre lo pactado (USD 500), pero podés elegir otro monto. Las reglas: (1) cada mes, al día ' + DIA_VENCE + ', tenés que llevar pagado del ciclo como mínimo la mitad de la cuota por cada mes que pasó (USD 250, 500, 750…); (2) el ciclo completo (USD 5.000) tiene que estar al día ' + DIA_VENCE + ' del mes de la compra; (3) lo que pongas de más adelanta los meses que vienen del mismo ciclo; (4) lo que pase de USD 5.000 en el ciclo es <b>aporte extra</b>: compra UP de más (hasta USD 2.500 por ciclo) y tu parte crece. Ejemplo: tres meses de USD 1.000 y siete de USD 500 son USD 6.500: USD 1.500 de extra, que agrandan la compra de ese ciclo y te dan más porcentaje de todas las ganancias. Todo compra UP al valor del cierre del mes (da lo mismo pagar el 1 o el 10) y el voto sigue siendo uno por persona. La app te dice, con cada monto, si quedás al día, cuántos meses adelantás y cuánto es extra.</p>'],
    ['¿Cómo pago mi aporte?', '<p>Del 1 al ' + DIA_VENCE + ' de cada mes transferís el aporte a la cuenta del fideicomiso, desde una cuenta a tu nombre. Después, en <b>Pagar</b>, tocá <b>«Ya transferí: avisar al fiduciario»</b>. El fiduciario lo confirma cuando lo ve en el banco y tus UP se compran con la fecha de tu aviso: la mora se cuenta hasta el día que transferiste, no hasta que se confirma. Mercado Pago y tarjeta se suman más adelante.</p>'],
    ['¿Quién ve mis datos en la versión real?', '<p>Tu nombre, tus aportes y tu parte los ven los socios de tu fideicomiso. Tu ficha (DNI, CUIT, domicilio, origen de los fondos) la ven solo vos y el fundador. Los mensajes privados del chat, solo vos y la otra persona. Cada socio puede escribir únicamente lo suyo (su voto, sus mensajes, su ficha, el aviso de su transferencia): los aportes, los inmuebles y las reglas del grupo los registra solo el fundador.</p>'],
    ['¿Qué es el número que aparece al lado de mi nombre, arriba?', '<p>Abajo de «EN VIVO» figura quién está conectado y, al lado, <b>cuánto ganó hasta hoy sobre lo que aportó</b>: lo que valen hoy sus UP comparado con todo lo que puso (por ejemplo, +2,4%). Se actualiza solo cada vez que cambia algo en el fideicomiso. Si lo tocás se abre <b>«Tu ganancia, explicada»</b>, la única ventana que explica tu plata (también se abre con «Mi parte hoy» y «Mi TIR» en Inicio y en Mis inversiones): cómo se calcula ese porcentaje; <b>Mi parte</b>: por qué es, por ejemplo, 10,03% y no 10% (todas las UP valen lo mismo para todos; cambia cuántas tiene cada uno); de dónde sale la ganancia (alquileres, rendimiento de la caja, mora, menos gastos e impuestos); qué es la TIR comparada con la meta del 6% y el plazo fijo; y <b>Mes a mes</b>: para cada mes, lo que aportaste, cuántas UP tenías, cuánto valían y a qué tasa rendía. Se cierra con «Volver».</p>'],
    ['¿Cómo presento el proyecto en vivo a varios celulares?', '<p>En <b>Cómo se usa → Presentación</b> tocá <b>«Abrir la sala en vivo»</b>. Aparece un QR: cada invitado lo escanea con la cámara y entra sin instalar nada ni crear cuenta. Lo que vos mostrás (láminas o la app de demostración, con sus ventanas) pasa al mismo tiempo en todos los teléfonos. Arriba ves cuántos están conectados y cuántos te siguen. <b>Soltar a todos</b>: cada uno explora la demo solo. <b>Traer a todos</b>: vuelven a tu pantalla. Cada invitado también puede tocar «Explorar solo» y «Volver con el presentador». Solo viaja qué pantalla se ve, nunca datos personales. Conviene que todos estén en el mismo wifi y que tu pantalla no se apague.</p>'],
    ['¿Cómo cierro la sesión?', '<p>Con el botón <b>Salir</b> que está arriba, al lado de la campanita (en el celular es el ícono de la puerta con la flecha). También en el menú ☰, abajo de todo, y en <b>Más → Cerrar sesión</b>. Si te olvidás, la sesión se cierra sola a los ' + MINUTOS_SESION + ' minutos sin uso.</p>'],
    ['Perdí el teléfono con Google Authenticator, ¿cómo entro?', '<p>Con tu correo, tu clave y <b>uno de tus códigos de recuperación</b> (los 10 que te dio la app al activar Google Authenticator). En el paso del código tocá <b>«¿Perdiste el teléfono? Usá un código de recuperación»</b> y escribilo. Cada código sirve una sola vez. Apenas entrás, la app te ofrece configurar Google Authenticator en el teléfono nuevo: desde ese momento el viejo ya no sirve. Si no tenés los códigos, pedile al fiduciario que te ayude a recuperar la cuenta.</p>'],
    ['¿Cómo entro con la huella o la cara?', '<p>Entrá una vez con correo y clave, andá a <b>Mis datos → Seguridad de la cuenta → Entrar con huella o cara</b> y tocá <b>«Activar en este equipo»</b>. Desde ahí, en ese teléfono, la entrada muestra un sensor dorado: tocalo, apoyá el dedo o mirá la cámara, y entrás. Funciona con la huella o la cara que ya usa tu teléfono; la huella nunca sale de él. Si la sesión se cierra por tiempo, volvés con la huella. Para sacarla, tocá «Quitar».</p>'],
    ['Me llegó «Entraron a tu cuenta desde un equipo nuevo», ¿qué hago?', '<p>Si fuiste vos desde otro teléfono o computadora, nada. Si no fuiste vos: cambiá tu clave ya (en Mis datos → Seguridad, o «¿Olvidaste tu clave?» en la entrada), revisá la lista de equipos y avisá al fiduciario. El aviso dice el tipo de equipo y la hora; nunca la ubicación.</p>'],
    ['Ya soy socio: ¿tengo que poner un código de invitación?', '<p><b>No.</b> El código de invitación se usa <b>una sola vez</b>, para crear la cuenta. Desde ahí entrás siempre por <b>«Ya soy socio»</b> (la opción que aparece elegida al abrir la app) con tu correo, tu clave y el código de 6 números de Google Authenticator. Si por error tocás «Tengo una invitación» y ponés tu correo, o usás una invitación que ya usaste, la app te pasa sola a «Ya soy socio» con el correo escrito. Si es tu primera vez, tocá el enlace del correo de invitación: abre la app con el código ya puesto.</p>'],
    ['En la proyección, ¿qué quiere decir «Mes 20» y por qué ahí se compra el segundo departamento?', '<p>Los meses se cuentan desde que empezó el fideicomiso: el mes 20 es <b>1 año y 8 meses después del primer aporte</b>. Como se compra cada 10 meses, las compras caen en los meses 10, 20, 30… hasta el 120: por eso en el mes 20 se compra el segundo departamento (en la opción B, «siempre 24 m²», las compras se van adelantando).</p>'],
    ['¿Qué son los «intereses de la caja mientras espera cada compra»?', '<p>Es lo que rindió la plata guardada mientras se juntaba para la próxima compra (cuenta remunerada, letras del Tesoro, fondos en dólares). Cada ciclo la caja va de cero a unos USD 50.000, en el mes 10 se gasta en el departamento y vuelve a empezar: el número suma lo de todos los ciclos desde el inicio. <b>Los departamentos no dan interés</b>: ganan por el alquiler y por la suba del m², que aparecen en sus propios renglones.</p>'],
    ['¿Por qué en la proyección se restan los gastos de compra y no el costo de vender?', '<p>Porque el fideicomiso compra y no vende. La escritura y los sellos (5% de cada compra) se pagaron de verdad, así que se restan. Vender costaría otro 5% (comisión y escribano), pero eso existiría solo si un día se vende todo: por eso la proyección muestra lo que vale tu parte sin vender nada, igual que la UP.</p>'],
    ['¿Y si la escritura cuesta más de 5%?', '<p>El 5% de gastos de compra (escribano, sellos y registro) es un <b>supuesto</b> de la app, no un dato confirmado de Tierra del Fuego. Las guías del país dan entre 5% y 8% según la provincia, y si interviene una inmobiliaria el comprador paga además su comisión (3% a 4%). Antes de la primera compra hay que pedir la proforma a un escribano de Ushuaia y, si da otro número, se corrige.</p>' +
      '<p>Cuánto cambia, con la misma regla (24 m² a USD 2.000): con 5% el departamento cuesta ' + usd(48000 * 1.05) + '; con 8%, ' + usd(48000 * 1.08) + '. En 10 años, con alquiler fijo: <b>' + gm.last.nProps + ' departamentos y TIR ' + pct(gm.irr) + '</b> con 5%, contra <b>' + g8.last.nProps + ' y ' + pct(g8.irr) + '</b> con 8%; el valor por socio pasa de ' + usd(gm.last.liq / N) + ' a ' + usd(g8.last.liq / N) + '.</p>'],
    ['¿Cuándo podemos dejar de aportar los USD 500 («rueda sola»)?', '<p>Cuando lo que el fideicomiso produce solo alcanza para seguir comprando. La app suma, con todo capitalizado, los alquileres y los intereses de la caja de los últimos 10 meses (la caja de aportes y alquileres rinde todos los meses; cada departamento sube con el m² y su alquiler sube con él) y lo compara con lo que cuesta ese mes un departamento de 24 m² con el m² indexado (3% por año en el escenario básico) más la escritura. El primer mes en que alcanza es el de «rueda sola». Después lo prueba: simula dejar de aportar desde ese mes y cuenta cuántos departamentos se siguen comprando en los 10 años siguientes. Lo ves en Inicio, en la proyección, para las dos maneras de comprar y con alquiler fijo y temporario. Dejar de aportar se vota (unanimidad).</p>'],
    ['¿Por qué la app me pide entrar de nuevo?', '<p>Por seguridad, como en el home banking: si pasan ' + MINUTOS_SESION + ' minutos sin que toques la app, la sesión se cierra sola y hay que volver a entrar con el correo, la clave y el código de Google Authenticator. Así, si dejás el teléfono a mano de otro, nadie ve tus datos.</p>'],
    ['¿Dónde están los términos y la privacidad?', '<p>Abajo de todo, en el pie de cada pantalla: <b>Términos y condiciones</b>, <b>Privacidad y datos personales</b>, <b>Qué NO es B&amp;D</b> (no es un juego, ni una especulación, ni un esquema piramidal) e <b>Impuestos (Tierra del Fuego)</b>. Ahí también figura quién desarrolló la app.</p>'],
    ['¿Qué es una UP?', '<p><b>UP es «unidad de participación»</b>: la porción del fideicomiso que es tuya, como la cuotaparte de un fondo. Al principio cada UP valía USD 100. Cada aporte compra UP al valor de ese día (si la UP vale USD 104, tus USD 500 compran 4,8 UP). Lo que vale tu parte es tus UP por el valor de la UP. Cuando el fideicomiso gana (alquileres, intereses, suba de los departamentos) sube el valor de cada UP y ganan todos por igual; quien paga tarde compra a un valor más alto y no se lleva lo que ganaron los demás.</p>'],
    ['¿Por qué en un grupo de 10 y no solo?',
      '<p>La cuenta, paso a paso, con los mismos USD 500 por mes y las mismas reglas (Ushuaia, USD 2.000 el m², escenario básico):</p><ol>' +
      '<li><b>Tiempo.</b> Solo, para juntar 24 m² con los gastos (USD 50.400) hacen falta ' + (mesSolo ? anios(mesSolo) : 'más de 10 años') + '. En grupo, la primera compra es en el mes 10. El alquiler empieza a trabajar ' + (mesSolo ? anios(mesSolo - 10) : 'años') + ' antes.</li>' +
      '<li><b>Interés compuesto.</b> Cada alquiler se reinvierte y compra más metros, que dan más alquiler: una bola de nieve. A los 10 años el grupo tiene ' + gm.last.nProps + ' departamentos; solo, ' + sm.last.nProps + ', que casi no llegó a alquilarse.</li>' +
      '<li><b>Resultado con la misma plata (USD 60.000 cada uno).</b> Alquiler fijo: <b>' + usd(gm.last.liq / N) + '</b> por socio en grupo (TIR ' + pct(gm.irr) + ') contra <b>' + usd(sm.last.liq) + '</b> solo (TIR ' + pct(sm.irr) + '). Temporario: <b>' + usd(gt.last.liq / N) + '</b> (TIR ' + pct(gt.irr) + ') contra <b>' + usd(st.last.liq) + '</b> (TIR ' + pct(st.irr) + ').</li>' +
      '<li><b>Diversificación.</b> Con ' + gm.last.nProps + ' departamentos, si uno queda vacío o un inquilino no paga se pierde una parte chica de la renta, no el 100%. Lo mismo con una reparación grande.</li>' +
      '<li><b>Escala.</b> Escribano, contador, tasaciones y administración se pagan entre 10. Y un grupo con caja cada 10 meses es un comprador atractivo: puede pagar de contado, negociar descuentos y entrar a remates, que exigen tener la plata lista.</li>' +
      '<li><b>Salida más fácil.</b> Tu parte son UP: podés salir con aviso de 90 días sin vender un departamento entero, y los demás tienen preferencia para comprarlas.</li>' +
      '<li><b>Disciplina.</b> La economía del comportamiento lo llama «compromiso previo»: cuando el aporte es un compromiso con otros, se paga todos los meses. Solo es más fácil postergarlo.</li></ol>' +
      '<p><b>Conclusión.</b> Si el alquiler rinde más que la plata esperando, y cuanto antes se compra antes empieza a rendir, entonces juntar la plata de 10 compra 10 veces más rápido y el rendimiento compuesto arranca años antes: con la misma plata se llega a más patrimonio y a más renta.</p>' +
      '<p><b>Lo que se resigna, con honestidad:</b> las decisiones se votan, se depende de que los demás paguen (la mora, la suspensión y la exclusión lo cubren), armar el fideicomiso tiene costos legales y cada uno tiene menos control individual.</p><p><button type="button" class="btn btn-oro btn-chico" data-abrir-sg>Ver la carrera: solo, con 5, 10 o 20 socios, en 7 mercados</button></p>'],
    ['Paso a paso para novatos: de cero al fideicomiso funcionando',
      '<p>Lo que hay que hacer, en orden, para pasar de la idea a un fideicomiso inscripto, con CUIT y cuenta en el banco. Los requisitos cambian: confirmalos con el escribano, el contador y cada organismo antes de ir. El trámite completo lleva semanas, no días, por los turnos de cada lugar.</p><ol class="pasos-novato">' +
      '<li><b>Armar el grupo en la app.</b> Los 10 socios, el aporte, el ciclo y las reglas. El fundador invita y cada uno se da de alta en 6 pasos (datos personales, fiscales, origen de fondos, CBU): así ya quedan juntos los datos que piden todos los trámites. Se decide quién es el fiduciario, el que administra: una persona de confianza o una sociedad (SAS) de los socios.</li>' +
      '<li><b>Reunión con los profesionales en Ushuaia.</b> Abogado (revisa el contrato y el estatuto), escribano (certifica las firmas) y contador (inscripciones e impuestos). Llevá impresos el contrato y el estatuto que arma la app (Contratos y Cómo se usa → Derechos y deberes) y la lista de socios.</li>' +
      '<li><b>Papeles de cada socio.</b> DNI vigente; constancia de CUIL o CUIT (se baja de la web de ARCA); comprobante de domicilio (un servicio a su nombre); estado civil y datos del cónyuge si corresponde; constancia de CBU de una cuenta a su nombre; declaración jurada de persona expuesta políticamente; declaración del origen de los fondos con respaldo (recibos de sueldo, declaración de Ganancias o Bienes personales, constancia de monotributo); beneficiario sustituto.</li>' +
      '<li><b>El fiduciario.</b> Si es una persona: DNI, CUIT, clave fiscal de ARCA nivel 3 y certificado de antecedentes penales (lo pide la UIF). Si es una SAS: primero se constituye en la Inspección General de Justicia de Tierra del Fuego y se le saca su CUIT. Verificá si tu cargo público es compatible con ser fiduciario.</li>' +
      '<li><b>Firmar el contrato de fideicomiso.</b> Por instrumento privado con las firmas certificadas por escribano, o por escritura pública (art. 1669 del Código Civil y Comercial; si desde el principio entra un inmueble, escritura). Cada socio firma además su contrato de adhesión con firma digital o ante escribano.</li>' +
      '<li><b>Inscribirlo en el Registro Público.</b> En Tierra del Fuego lo lleva la Inspección General de Justicia provincial, en Ushuaia. Lo pide el fiduciario. Se lleva: el contrato original con firmas certificadas y copias, el formulario y la tasa, y las declaraciones juradas (persona expuesta políticamente y beneficiarios finales). Preguntá antes la lista actual de requisitos.</li>' +
      '<li><b>CUIT del fideicomiso en ARCA.</b> El fiduciario, con su clave fiscal, en el servicio de inscripción de personas jurídicas (o con turno en la agencia de Ushuaia). Presenta el contrato inscripto, su DNI (o la documentación de la sociedad fiduciaria) y una nota con carácter de declaración jurada que identifica al fideicomiso (resolución general de ARCA de diciembre de 2025, anexo II, fideicomisos no financieros). Se adhiere al domicilio fiscal electrónico. Con el contador se dan de alta los impuestos que correspondan y el régimen anual de información de fideicomisos (RG 3312: vence a fines de julio e incluye los beneficiarios finales).</li>' +
      '<li><b>Ingresos brutos en la AREF.</b> La Agencia de Recaudación Fueguina: alta con clave fiscal en aref.gob.ar, con la actividad de alquiler de inmuebles. Si se alquila temporario a turistas, consultá además al InFueTur (Instituto Fueguino de Turismo) y a la Municipalidad de Ushuaia por el registro y la habilitación.</li>' +
      '<li><b>UIF (prevención del lavado de dinero).</b> El fiduciario es sujeto obligado (Ley 25.246, art. 20). Se inscribe en el sistema de la UIF con sus declaraciones juradas, antecedentes penales y copia de los contratos de fideicomiso inscriptos; designa un oficial de cumplimiento; arma el manual de prevención y el legajo de cada socio (la app ya lo junta en el alta) e informa los cambios de beneficiarios finales dentro de los 30 días.</li>' +
      '<li><b>Cuenta bancaria del fideicomiso.</b> En un banco (por ejemplo Banco de Tierra del Fuego o Banco Nación), cuenta en pesos y en dólares a nombre del fideicomiso, con el fiduciario como firmante. Se lleva: contrato inscripto, constancia de CUIT del fideicomiso, constancia de la AREF, DNI y CUIT del fiduciario, declaraciones de persona expuesta políticamente y de sujeto obligado ante la UIF, la nómina de beneficiarios finales (cada socio con 10% o más) y el origen de los fondos. Pedí el CBU y el alias.</li>' +
      '<li><b>Cobros.</b> Cuenta de Mercado Pago a nombre del fideicomiso (con su CUIT). Se cargan el CBU, el alias y Mercado Pago en la app y cada socio paga del 1 al 10.</li>' +
      '<li><b>Funcionar.</b> El contador lleva los libros (la app arma la carpeta diaria, semanal y mensual) y el balance anual. Antes de cada compra: tasación, estudio de títulos, escritura ante escribano, inscripción en el Registro de la Propiedad Inmueble de Tierra del Fuego y seguro de incendio y responsabilidad civil.</li></ol>' +
      '<p class="chico">Fuentes: Código Civil y Comercial (arts. 1666 a 1700); ARCA, inscripción de fideicomisos no financieros (anexo II de la resolución general de diciembre de 2025) y régimen de información RG 3312; Ley 25.246 y resoluciones UIF 50/2011, 47/2024 y 37/2026; AREF. No reemplaza al abogado, al escribano ni al contador.</p>'],
    ['¿Qué pasa si un socio se quiere quedar con un departamento?',
      '<p>Se puede. Lo pide desde Votaciones o tocando el departamento en Inicio, con la tasación de un tasador independiente. El precio es el mayor entre la tasación y lo que costó. Vota la Asamblea con mayoría calificada sin el voto del comprador. Si se aprueba, el comprador paga a los demás la parte que les toca y su propia parte se cancela con sus UP: el valor de la UP de los demás no cambia. Después se vota qué hacer con la plata: sumarla a la próxima compra, comprar un departamento de reemplazo o invertirla en la espera. El fiduciario no puede comprar (art. 1676 del Código Civil y Comercial).</p>'],
    ['¿Alquiler fijo o temporario?',
      '<p>La app muestra siempre las dos modalidades. Con los números de hoy (escenario básico, 10 años, valor del grupo):</p><div class="tabla-scroll"><table><tr><th>Ciudad</th><th class="n">Fijo</th><th class="n">Temporario</th></tr>' +
      '<tr><td>Ushuaia</td><td class="n">' + usd(gm.last.liq) + ' · ' + pct(gm.irr) + '</td><td class="n">' + usd(gt.last.liq) + ' · ' + pct(gt.irr) + '</td></tr>' +
      '<tr><td>Buenos Aires (CABA)</td><td class="n">' + usd(bm.last.liq) + ' · ' + pct(bm.irr) + '</td><td class="n">' + usd(bt.last.liq) + ' · ' + pct(bt.irr) + '</td></tr></table></div>' +
      '<p>En Ushuaia el temporario rinde más por el turismo. En Buenos Aires hoy da casi lo mismo: el alquiler fijo de 24 m² está entre $450.000 y $900.000 por mes (la app usa USD ' + M.rent24 + ', unos $' + num(Math.round(M.rent24 * tcAporte() / 1000) * 1000) + ' al dólar de hoy) y el temporario factura unos USD ' + num(brutoT) + ' brutos por mes (alrededor de USD 40 la noche con 72% de ocupación), pero se va 40% en limpieza, plataforma y administración, más los muebles. Además, el temporario necesita que el reglamento del edificio lo permita.</p>'],
    ['¿Conviene tomar un préstamo para crecer más rápido?', '<p><b>Sí, con condiciones.</b> Se llama apalancamiento positivo: si el departamento comprado con el préstamo rinde más de lo que cuesta el préstamo, la diferencia es ganancia extra. Pero se compara con lo que rinde el departamento (renta neta + suba del m², unos 11% por año en Ushuaia con alquiler fijo), no con la TIR del fideicomiso, porque los aportes no son ganancia. Las condiciones: préstamo en dólares y a tasa fija (un crédito ajustado por inflación contra rentas en dólares es una apuesta); la renta cubre al menos 1,3 veces la cuota; la deuda no pasa del 40% del patrimonio; ningún socio da garantía personal; y pasa la prueba de estrés (alquiler −20%, sin suba, tasa +3 puntos). En Oportunidades → «Préstamo para comprar más» la app hace la cuenta con y sin préstamo y dice si favorece. Lo vota la Asamblea con mayoría calificada.</p>'],
    ['¿Se puede comprar sin tener toda la plata?', '<p>Sí: si el vendedor necesita plata rápido, se le paga de contado lo que hay en caja y el saldo en cuotas fijas en dólares, sin interés ni indexación, que vencen del 1 al 10 como los aportes. Cada oportunidad trae la calculadora «¿Y si el vendedor financia el saldo?» con la cuota, los vencimientos, cuánto pesa en lo que entra por mes y una propuesta lista para mandarle. Tope del estatuto: saldo de hasta 30% del costo y hasta 12 cuotas; lo vota la Asamblea con mayoría calificada. La deuda se ve en Saldos deudores y se descuenta del valor de la UP mientras se paga.</p>'],
    ['¿Cuánto tengo que aportar para cobrar una renta por mes?', '<p>Usá «Mi meta de ingresos» en el menú: movés las barras con la renta que querés y en cuántos años, y la app te dice cuánto aportar, en qué año llegás y qué caminos te acercan más.</p>'],
    ['¿Puedo salir antes? ¿Y si me pasa algo?', '<p>Podés retirarte con aviso de 90 días: se te reembolsa el valor de tus UP en hasta 12 cuotas, sin obligar a vender un departamento, y los demás tienen preferencia para comprarlas. Si fallecés, tus UP pasan al beneficiario sustituto que designaste o a tus herederos, que se unifican en un representante con un voto.</p>'],
    ['¿Por qué un fideicomiso y no una sociedad o un fondo?', '<p>El fideicomiso separa los bienes del patrimonio de cada socio y del fiduciario (no responden por sus deudas personales), permite entrar y salir con UP y, si todos los que aportan son también beneficiarios y viven en el país, el contador puede atribuir la ganancia a cada socio. Un fondo común de inversión necesita una sociedad gerente autorizada por la CNV. Una SAS es la alternativa si el abogado lo prefiere.</p>'],
    ['¿Cómo me entero a tiempo de una oportunidad?', '<p>A las 12 del mediodía llega el aviso «🚨 Oportunidad única» con el link que abre la oferta y la votación exprés de 24 horas. Llega a la campanita y, si los activás en Mis datos → «Avisos por varios canales», también por correo, ntfy, Telegram y WhatsApp, todo gratis. Los avisos no llevan nombres ni montos; el detalle se ve adentro de la app.</p>'],
    ['¿Quién ve mis datos?', '<p>Tus datos personales y fiscales los ven vos y el fiduciario (cada vez que los abre queda anotado). Los demás socios ven tu nombre, tus aportes y tu participación. Quien solo mira no ve ningún dato personal. Tus argumentos y tus motivos en los debates los ven solo los socios de tu fideicomiso. Tus canales de aviso (teléfono de WhatsApp, chat de Telegram y clave de CallMeBot) los ves solo vos y el servidor que manda los avisos, que nunca llevan nombres ni montos. De los inquilinos, los datos los ve solo el fiduciario y el contacto se borra al terminar el contrato. Podés bajar tus datos o pedir la baja desde Mis datos (Ley 25.326).</p>']
  ];
  return acordeon(Q);
}

/* ---------------- derechos y deberes ---------------- */
function grupoParaTextos() { return grupoActual() || { letra: 'Alfa', N: 10, aporte: 500, ciclo: 10, fee: 0, fiduciario: null }; }
function ayudaEstatuto(u) {
  var g = grupoParaTextos(), socio = u.rol !== 'observador' && grupoActual();
  return '<div class="fila seccion">' + (socio ? '<button class="btn btn-oro" id="btnMiAdhesion">' + (u.rol === 'fundador' ? 'Contrato de adhesión de cada socio' : 'Mi contrato de adhesión') + '</button>' : '') +
    '<button class="btn" id="btnBajarEstatuto">Bajar el estatuto (.txt)</button><button class="btn" id="btnImprimirEstatuto">Imprimir o guardar en PDF</button></div>' +
    '<section class="tarjeta seccion">' + htmlEstatuto(g) + '</section>';
}

/* ---------------- presentación ---------------- */
var VISOR = { deck: null, slides: {}, i: 0 };
function ayudaPresentacion() {
  return '<div class="tarjeta dorada seccion"><b>Presentar en vivo a los celulares</b><p class="chico gris" style="margin:4px 0 10px">Abrís la sala, mostrás un QR y cada invitado ve en su teléfono o tablet las láminas y la app que vos vas pasando, en vivo. Con «Soltar a todos» cada uno explora la demo solo; con «Traer a todos» vuelven a tu pantalla.</p><a class="btn btn-oro" href="sala.html?presentar" target="_blank" rel="noopener">Abrir la sala en vivo</a></div>' +
    '<div class="visor seccion" id="visor" tabindex="0" aria-label="Presentación. Usá las flechas del teclado para pasar las láminas.">' +
    '<div class="visor-barra"><div class="fila"><button class="btn btn-chico" id="visorAnt" aria-label="Lámina anterior">◀</button><b id="visorNum" class="num">…</b><button class="btn btn-chico" id="visorSig" aria-label="Lámina siguiente">▶</button></div>' +
    '<div class="fila"><select id="visorSel" aria-label="Ir a una lámina"></select><button class="btn btn-chico" id="visorNotas" aria-pressed="false">Notas</button><button class="btn btn-chico btn-oro" id="visorPantalla">Pantalla completa</button></div></div>' +
    '<div class="visor-lamina" id="visorLamina"><div id="visorLienzo"><p style="padding:60px;font-size:40px;color:#9FB0C4">Cargando la presentación…</p></div></div>' +
    '<div class="visor-notas" id="visorTextoNotas" hidden></div></div>' +
    '<p class="chico gris">Son ' + 'las láminas para la reunión con los socios, con los mismos números que la app. En pantalla completa se pasan con las flechas o tocando los costados.</p>';
}
function cargarDeck() {
  if (VISOR.deck) return Promise.resolve(VISOR.deck);
  return fetch('presentacion/deck.json').then(function (r) { return r.json(); }).then(function (d) { VISOR.deck = d; return d; });
}
function cargarLamina(id) {
  if (VISOR.slides[id]) return Promise.resolve(VISOR.slides[id]);
  return fetch('presentacion/slides/' + id + '.html').then(function (r) { return r.text(); }).then(function (t) { VISOR.slides[id] = t; return t; });
}
function escalarLamina() { var c = $('visorLamina'), l = $('visorLienzo'); if (c && l) l.style.transform = 'scale(' + (c.clientWidth / 1920) + ')'; }
function mostrarLamina(i) {
  var d = VISOR.deck; if (!d) return; i = Math.max(0, Math.min(d.order.length - 1, i)); VISOR.i = i;
  var id = d.order[i];
  cargarLamina(id).then(function (html) {
    if (!$('visorLienzo')) return;
    $('visorLienzo').innerHTML = html; escalarLamina();
    var aside = $('visorLienzo').querySelector('aside');
    $('visorTextoNotas').textContent = aside ? aside.textContent : 'Esta lámina no tiene notas.';
    $('visorNum').textContent = (i + 1) + ' / ' + d.order.length; $('visorSel').value = String(i);
    if (d.order[i + 1]) cargarLamina(d.order[i + 1]);
  });
}
function ganchoPresentacion() {
  cargarDeck().then(function (d) {
    if (!$('visorSel')) return;
    $('visorSel').innerHTML = d.order.map(function (id, k) { return '<option value="' + k + '">' + (k + 1) + '. ' + id.replace(/-/g, ' ') + '</option>'; }).join('');
    mostrarLamina(VISOR.i || 0);
  }).catch(function () { if ($('visorLienzo')) $('visorLienzo').innerHTML = '<p style="padding:60px;font-size:40px;color:#FF9284">No se pudo cargar la presentación. Abrí la app desde su dirección web (no como archivo).</p>'; });
  $('visorAnt').onclick = function () { mostrarLamina(VISOR.i - 1); };
  $('visorSig').onclick = function () { mostrarLamina(VISOR.i + 1); };
  $('visorSel').onchange = function () { mostrarLamina(+this.value); };
  $('visorNotas').onclick = function () { var n = $('visorTextoNotas'); n.hidden = !n.hidden; this.setAttribute('aria-pressed', !n.hidden); };
  $('visorPantalla').onclick = function () { var v = $('visor'); if (document.fullscreenElement) document.exitFullscreen(); else if (v.requestFullscreen) v.requestFullscreen(); else if (v.webkitRequestFullscreen) v.webkitRequestFullscreen(); };
  $('visorLamina').onclick = function (e) { var r = this.getBoundingClientRect(); mostrarLamina(VISOR.i + (e.clientX - r.left < r.width / 3 ? -1 : 1)); };
  $('visor').onkeydown = function (e) { if (e.key === 'ArrowRight' || e.key === 'PageDown' || e.key === ' ') { e.preventDefault(); mostrarLamina(VISOR.i + 1); } if (e.key === 'ArrowLeft' || e.key === 'PageUp') { e.preventDefault(); mostrarLamina(VISOR.i - 1); } };
  if (!ganchoPresentacion.escucha) { ganchoPresentacion.escucha = true; window.addEventListener('resize', escalarLamina); document.addEventListener('fullscreenchange', function () { setTimeout(escalarLamina, 60); }); }
}

/* ---------------- simulador y demo ---------------- */
function ayudaSimulador() {
  return '<p class="gris">El simulador completo: mercados, alquiler fijo y temporario, escenarios, rueda sola, grupos griegos y la meta de ingresos. Usa el mismo motor de cálculo que la app.</p>' +
    '<div class="fila" style="margin-bottom:10px"><a class="btn btn-chico" href="simulador.html" target="_blank" rel="noopener">Abrir en otra pestaña</a></div>' +
    '<iframe class="marco-embebido" src="simulador.html" title="Simulador B&amp;D" loading="lazy"></iframe>';
}
function ayudaDemo() {
  if (MARCO_DEMO) return '<p class="gris">Estás adentro de la demo. Para ver los cuatro celulares, abrí la demo desde la app en una computadora.</p>';
  return '<p class="gris">Cuatro celulares con la app de verdad, cada uno con su perfil: el socio fundador, una socia, alguien que se suma a otro grupo y alguien que solo mira. Los cuatro comparten los datos de prueba de este equipo.</p>' +
    '<div class="fila" style="margin-bottom:10px"><a class="btn btn-chico btn-oro" href="demo.html" target="_blank" rel="noopener">Abrir la demo en otra pestaña (recomendado)</a></div>' +
    '<iframe class="marco-embebido" src="demo.html" title="Demo con cuatro celulares" loading="lazy"></iframe>';
}

/* ---------------- comportamiento ---------------- */
function ganchoAyuda(r) {
  var t = (r && r.q.t) || 'manual';
  if (t === 'presentacion') ganchoPresentacion();
  if (t === 'estatuto') {
    var g = grupoParaTextos();
    if ($('btnMiAdhesion')) $('btnMiAdhesion').onclick = function () { ventana(function () { ventanaAdhesionSocio(); }); };
    $('btnBajarEstatuto').onclick = function () { descargar('BD-' + g.letra + '-estatuto-derechos-y-deberes.txt', textoEstatuto(g), 'text/plain;charset=utf-8'); };
    $('btnImprimirEstatuto').onclick = function () { window.print(); };
  }
}
